//! Randomised attempts to falsify, on this implementation, the theorems of
//! the paper. Each test names the result it attacks. Inputs are generated by
//! a fixed-seed generator, so failures are reproducible.

mod common;
use common::Rng;
use maisa_core::design::*;
use maisa_core::*;

fn acc(alpha: f64, z0: f64) -> Accumulator {
    Accumulator::new(alpha, z0, f64::INFINITY).unwrap()
}

#[test]
fn lemma_5_2_sampling_invariance() {
    let mut r = Rng(1);
    for _ in 0..20_000 {
        let alpha = r.log_uniform(1e-3, 1e3);
        let (d1, d2) = (
            r.log_uniform(1e-6, 5.0) / alpha,
            r.log_uniform(1e-6, 5.0) / alpha,
        );
        let p = r.uniform(0.0, 10.0);
        let z0 = r.uniform(0.0, 10.0);
        let mut a = acc(alpha, z0);
        a.step(p, d1, true);
        a.step(p, d2, true);
        let mut b = acc(alpha, z0);
        b.step(p, d1 + d2, true);
        assert!(common::close(a.value(), b.value()) || (a.value() - b.value()).abs() < 1e-13);
    }
}

#[test]
fn theorem_5_3_invariance_and_5_4_comparison() {
    let mut r = Rng(2);
    for _ in 0..2_000 {
        let alpha = r.log_uniform(1e-3, 1e3);
        let p_max = r.log_uniform(1e-3, 1e3);
        let z0 = r.uniform(0.0, 2.0 * p_max / alpha);
        let bound = z0.max(p_max / alpha);
        let mut a = acc(alpha, z0);
        let mut b = acc(alpha, z0 + r.unit());
        for _ in 0..200 {
            let dt = r.log_uniform(1e-6, 10.0) / alpha;
            let valid = r.chance(0.9);
            let p1 = r.uniform(0.0, p_max);
            let p2 = p1 + r.uniform(0.0, p_max);
            let before = a.value();
            let out = a.step(p1, dt, valid);
            b.step(p2, dt, valid);
            assert!(a.value() >= 0.0);
            assert!(a.value() <= bound * (1.0 + 1e-12));
            assert!(a.value() <= b.value() * (1.0 + 1e-12) + 1e-300);
            if !valid {
                assert_eq!(out, StepOutcome::Held);
                assert_eq!(
                    a.value().to_bits(),
                    before.to_bits(),
                    "a gated tick must hold exactly"
                );
            }
        }
    }
}

#[test]
fn theorem_5_5_detection_time_and_5_6_sharpness() {
    let mut r = Rng(3);
    for _ in 0..3_000 {
        let alpha = r.log_uniform(1e-2, 1e2);
        let zc = r.log_uniform(1e-2, 1e2);
        let p0 = alpha * zc * r.uniform(1.01, 5.0);
        let z0 = r.uniform(0.0, zc * 0.99);
        let t_star = time_to_threshold(alpha, p0, zc, 0.0);
        assert!(time_to_threshold(alpha, p0, zc, z0) <= t_star);
        let dt_max = 0.3 / alpha;
        let mut a = acc(alpha, z0);
        let mut t = 0.0;
        let mut first: Option<f64> = None;
        while t < 3.0 * t_star + 1.0 / alpha {
            let dt = r.log_uniform(1e-3, 0.3) / alpha;
            a.step(p0 * r.uniform(1.0, 1.5), dt, true);
            t += dt;
            if first.is_none() && a.value() >= zc {
                first = Some(t);
            }
            if t >= t_star * (1.0 + 1e-9) + 1e-12 {
                assert!(a.value() >= zc * (1.0 - 1e-12));
            }
        }
        // Theorem 5.5 (c): first crossing before T* + dt_max.
        assert!(first.unwrap() < t_star + dt_max + 1e-9);
        // Theorem 5.6: at or below alpha*zc, never reached.
        let mut s = acc(alpha, z0);
        for _ in 0..300 {
            s.step(
                alpha * zc * r.unit(),
                r.log_uniform(1e-3, 50.0) / alpha,
                r.chance(0.9),
            );
            assert!(s.value() < zc);
        }
    }
}

#[test]
fn theorem_4_7_intermittent_faults() {
    let mut r = Rng(4);
    for _ in 0..1_500 {
        let alpha = r.log_uniform(1e-2, 1e1);
        let p0 = r.log_uniform(1e-1, 1e2);
        let (t_on, t_off) = (
            r.log_uniform(1e-2, 2.0) / alpha,
            r.log_uniform(1e-2, 2.0) / alpha,
        );
        let m_inf = intermittent_peak_limit(alpha, p0, t_on, t_off);
        let detect = r.chance(0.5);
        let zc = m_inf
            * if detect {
                r.uniform(0.05, 0.97)
            } else {
                r.uniform(1.0001, 1.5)
            };
        let n_pred = intermittent_cycles_to_threshold(alpha, p0, t_on, t_off, zc);
        let mut a = acc(alpha, 0.0);
        let mut n_obs = f64::INFINITY;
        for n in 1..4000 {
            a.step(p0, t_on, true);
            assert!(
                a.value() < m_inf * (1.0 + 1e-12),
                "peak exceeds the supremum"
            );
            if a.value() >= zc {
                n_obs = n as f64;
                break;
            }
            a.step(0.0, t_off, true);
        }
        if detect {
            let x = (m_inf / (m_inf - zc)).ln() / (alpha * (t_on + t_off));
            let on_boundary = (x - x.round()).abs() < 1e-9;
            assert!(n_obs == n_pred || (on_boundary && (n_obs - n_pred).abs() == 1.0));
        } else {
            assert!(n_obs.is_infinite() && n_pred.is_infinite());
        }
    }
}

#[test]
fn proposition_5_10_saturation() {
    let mut r = Rng(5);
    for _ in 0..2_000 {
        let alpha = r.log_uniform(1e-2, 1e2);
        let p_max = r.log_uniform(1e-1, 1e2);
        let zc = r.uniform(0.1, 0.9) * p_max / alpha;
        let z_max = zc * r.uniform(1.0, 1.3);
        let mut ideal = acc(alpha, 0.0);
        let mut sat = Accumulator::new(alpha, 0.0, z_max).unwrap();
        let (mut f1, mut f2) = (None, None);
        for k in 0..300 {
            let dt = r.log_uniform(1e-3, 1.0) / alpha;
            let p = r.uniform(0.0, p_max);
            ideal.step(p, dt, true);
            sat.step(p, dt, true);
            assert!(sat.value() <= ideal.value());
            assert!(sat.value() <= z_max);
            assert_eq!(sat.saturated(), sat.saturated() || sat.value() == z_max);
            if f1.is_none() && ideal.value() >= zc {
                f1 = Some(k);
            }
            if f2.is_none() && sat.value() >= zc {
                f2 = Some(k);
            }
        }
        assert_eq!(f1, f2, "saturation changed the first critical crossing");
        // (c): a cap at or above P/alpha is never active
        let mut c = Accumulator::new(alpha, 0.0, p_max / alpha * (1.0 + 1e-9)).unwrap();
        for _ in 0..300 {
            c.step(
                r.uniform(0.0, p_max),
                r.log_uniform(1e-3, 1.0) / alpha,
                true,
            );
        }
        assert!(!c.saturated());
    }
}

#[test]
fn theorem_7_3_warning_soundness_and_bounded_chatter() {
    let mut r = Rng(6);
    let mut tightest = f64::INFINITY;
    for _ in 0..800 {
        let alpha = r.log_uniform(0.1, 10.0);
        let p_max = r.log_uniform(0.5, 50.0);
        let z_inf = p_max / alpha;
        let zen = z_inf * r.uniform(0.2, 0.95);
        let zex = zen * r.uniform(0.1, 0.9);
        let tst = r.log_uniform(0.05, 3.0) / alpha;
        let tau = rise_time(alpha, p_max, zex, zen);
        let mut a = acc(alpha, r.uniform(0.0, z_inf));
        let mut h = Hysteresis::new(zen, zex, tst, true).unwrap();
        let (mut t, mut prev, mut last_entry) = (0.0, true, None::<f64>);
        let mut drive = false;
        let mut below_run = 0.0;
        for _ in 0..3000 {
            let dt = r.log_uniform(1e-3, 0.3) / alpha;
            t += dt;
            let valid = r.chance(0.93);
            // adversary: push up as soon as the flag falls, relax once it is set
            if !h.flag() {
                drive = true;
            } else if a.value() >= zen {
                drive = false;
            }
            if r.chance(0.02) {
                drive = !drive;
            }
            a.step(if drive { p_max } else { 0.0 }, dt, valid);
            let w = h.step(a.value(), t, valid);
            if a.value() >= zen {
                assert!(w, "z >= z_enter but flag clear");
            }
            if !w {
                assert!(a.value() < zen);
            }
            // independent re-derivation of the clearing rule
            if valid && a.value() <= zex {
                below_run += dt;
            } else {
                below_run = 0.0;
            }
            if prev && !w {
                assert!(valid && a.value() <= zex);
            }
            let _ = below_run;
            if w && !prev {
                if let Some(t0) = last_entry {
                    let gap = t - t0;
                    assert!(
                        gap > tst + tau - 1e-9,
                        "chatter bound violated: {gap} vs {}",
                        tst + tau
                    );
                    tightest = tightest.min(gap / (tst + tau));
                }
                last_entry = Some(t);
            }
            prev = w;
        }
    }
    assert!(tightest >= 1.0);
}

#[test]
fn theorem_7_14_bounded_intervention() {
    let mut r = Rng(7);
    for _ in 0..1_500 {
        let n_max = 1 + r.below(6) as usize;
        let (tcd, tto) = (r.log_uniform(0.1, 5.0), r.log_uniform(0.1, 5.0));
        let mut e = InterventionEngine::<6>::new(n_max, tcd, tto).unwrap();
        let mut t = 0.0;
        let mut accepted: Vec<f64> = Vec::new();
        let mut since_reset: Vec<u32> = Vec::new();
        let mut open: Vec<(u32, f64)> = Vec::new();
        for _ in 0..400 {
            t += r.log_uniform(1e-3, 2.0);
            if r.chance(0.03) {
                e.authorised_reset();
                since_reset.clear();
                open.clear();
                assert_eq!(e.attempts(), 0);
                assert!(!e.escalated());
            } else {
                let id = r.below(13) as u32;
                let before = e.attempts();
                let o = e.request(t, id, r.chance(0.9));
                match o {
                    Outcome::Accepted => {
                        assert!(!since_reset.contains(&id), "identifier accepted twice");
                        assert_eq!(e.attempts(), before + 1);
                        since_reset.push(id);
                        accepted.push(t);
                        open.push((id, t));
                    }
                    Outcome::RejectedLimit => {
                        assert_eq!(before, n_max);
                        assert!(e.escalated(), "exhausted budget must escalate");
                    }
                    _ => assert_eq!(e.attempts(), before),
                }
                e.tick(t);
                open.retain(|&(_, t0)| t - t0 < tto);
                assert_eq!(e.pending(), open.len(), "timeout bookkeeping");
            }
            assert!(e.attempts() <= n_max && since_reset.len() <= n_max);
        }
        for w in accepted.windows(2) {
            assert!(w[1] - w[0] >= tcd, "cooldown violated across resets");
        }
        let win = r.log_uniform(0.5, 20.0);
        for (i, &a0) in accepted.iter().enumerate() {
            let cnt = accepted[i..].iter().filter(|&&a| a - a0 <= win).count();
            assert!(cnt as f64 <= 1.0 + (win / tcd).floor());
        }
    }
}

fn monitor(alpha: f64, zc: f64, dt_max: f64, latch: bool) -> Monitor<3> {
    let c = ChannelConfig {
        alpha,
        z_crit: zc,
        z_enter: zc * 0.5,
        z_exit: zc * 0.25,
        t_stable: 1.0,
        z_max: f64::INFINITY,
        guard_band: 0.0,
        required: true,
        z0: 0.0,
        w0: false,
    };
    Monitor::new(&[c; 3], dt_max, latch, 0.0).unwrap()
}

const NONE: External = External {
    h: false,
    s: false,
    x: false,
    k: false,
    r: false,
    a: false,
};

#[test]
fn theorem_8_1_no_alarm_in_nominal_operation() {
    let mut r = Rng(8);
    for _ in 0..400 {
        let alpha = r.log_uniform(0.1, 10.0);
        let eps = r.uniform(0.0, 0.3);
        let (lo, hi, s) = (-1.0, 1.0, 1.0);
        let dead = eps / s;
        let mut m = monitor(alpha, 5.0, 1.0, false);
        let mut t = 0.0;
        for _ in 0..500 {
            t += r.uniform(0.01, 1.0);
            let mut smp = [Sample::default(); 3];
            for x in smp.iter_mut() {
                let truth = r.uniform(lo, hi);
                let y = truth + r.uniform(-eps, eps);
                *x = Sample {
                    p: response(deviation(y, lo, hi, s), dead, 1.0),
                    valid: true,
                };
                assert_eq!(x.p, 0.0, "Proposition 3.6 (a): no false drive");
            }
            let out = m.tick(t, &smp, NONE);
            assert_eq!(out.state, State::Normal);
            assert!(!out.latch && !out.request_safe_state);
        }
    }
}

#[test]
fn theorem_8_2_conditional_detection_and_8_3_restart_safety() {
    let mut r = Rng(9);
    for _ in 0..1_500 {
        let alpha = r.log_uniform(0.1, 10.0);
        let eps = r.uniform(0.0, 0.2);
        let (lo, hi, s) = (-1.0, 1.0, 1.0);
        let dead = eps / s;
        let w = r.log_uniform(0.5, 5.0);
        let zc = r.log_uniform(0.5, 5.0);
        let theta = dead + (alpha * zc / w) * r.uniform(1.05, 4.0) + eps / s;
        let u_min = w * (theta - eps / s - dead);
        let t_star = time_to_threshold(alpha, u_min, zc, 0.0);
        let dt_max = r.log_uniform(0.01, 0.5) / alpha;
        // restart safety: the monitor starts from zeroed accumulators, with
        // or without a nominal phase before the fault
        let mut m = monitor(alpha, zc, dt_max, false);
        let mut t = 0.0;
        for _ in 0..r.below(50) {
            t += r.uniform(0.2, 1.0) * dt_max;
            m.tick(
                t,
                &[Sample {
                    p: 0.0,
                    valid: true,
                }; 3],
                NONE,
            );
        }
        let t0 = t;
        let axis = r.below(3) as usize;
        let mut detected = None;
        let mut requests = 0;
        while t - t0 < t_star + 3.0 * dt_max {
            t += r.uniform(0.2, 1.0) * dt_max;
            let excess = theta * s * r.uniform(1.0, 2.0);
            let truth = if r.chance(0.5) {
                hi + excess
            } else {
                lo - excess
            };
            let y = truth + r.uniform(-eps, eps);
            let mut smp = [Sample {
                p: 0.0,
                valid: true,
            }; 3];
            smp[axis].p = w * response(deviation(y, lo, hi, s), dead, 1.0);
            assert!(
                smp[axis].p >= u_min * (1.0 - 1e-12),
                "Proposition 3.6 (b): guaranteed drive"
            );
            let out = m.tick(t, &smp, NONE);
            requests += out.request_safe_state as u32;
            if detected.is_none() && out.latch {
                detected = Some(t);
                assert_eq!(out.state, State::SafeRequested);
                assert!(out.latch_changed && out.request_safe_state);
            }
            if t - t0 >= t_star {
                assert!(out.latch && out.state.is_intervention());
            }
        }
        assert!(
            detected.unwrap() - t0 <= t_star + dt_max + 1e-9,
            "detection later than T* + dt_max"
        );
        assert_eq!(requests, 1, "exactly one safe-state request");
        // Theorem 7.10 in the assembled monitor: no release without a reset.
        for _ in 0..300 {
            t += r.uniform(0.2, 1.0) * dt_max;
            let ext = External {
                k: r.chance(0.5),
                r: r.chance(0.5),
                a: false,
                ..NONE
            };
            let out = m.tick(
                t,
                &[Sample {
                    p: 0.0,
                    valid: true,
                }; 3],
                ext,
            );
            assert!(out.latch && out.state != State::Normal);
        }
    }
}

#[test]
fn full_fault_and_recovery_cycle() {
    let (alpha, zc) = (1.0, 0.6);
    let mut m = monitor(alpha, zc, 0.05, false);
    let dt = 0.01;
    let mut t = 0.0;
    let nominal = [Sample {
        p: 0.0,
        valid: true,
    }; 3];
    let mut faulty = nominal;
    faulty[1].p = 0.9;
    let mut tick = |m: &mut Monitor<3>, s: &[Sample; 3], e: External| {
        t += dt;
        m.tick(t, s, e)
    };
    assert_eq!(tick(&mut m, &nominal, NONE).state, State::Normal);
    // fault: warning first, then critical at T* = ln 3
    let mut saw_degraded = false;
    let mut steps = 0;
    loop {
        let out = tick(&mut m, &faulty, NONE);
        steps += 1;
        if out.state == State::Degraded {
            saw_degraded = true;
        }
        if out.latch {
            assert_eq!(out.state, State::SafeRequested);
            break;
        }
        assert!(steps < 1000);
    }
    assert!(saw_degraded);
    let detected_after = steps as f64 * dt;
    assert!(
        (detected_after - 3f64.ln()).abs() <= dt + 1e-9,
        "detected after {detected_after}"
    );
    // confirmation moves to SafeConfirmed; the accumulator is still critical
    let k = External { k: true, ..NONE };
    assert_eq!(tick(&mut m, &nominal, k).state, State::SafeConfirmed);
    // without confirmation it falls back to a request
    assert_eq!(tick(&mut m, &nominal, NONE).state, State::SafeRequested);
    assert_eq!(tick(&mut m, &nominal, k).state, State::SafeConfirmed);
    // the accumulator decays below critical: LockedRecovery, even with a premature reset
    let premature = External {
        k: true,
        r: true,
        a: true,
        ..NONE
    };
    let mut out = tick(&mut m, &nominal, premature);
    let mut guard = 0;
    while out.state == State::SafeConfirmed {
        out = tick(&mut m, &nominal, premature);
        guard += 1;
        assert!(guard < 10_000);
    }
    assert_eq!(out.state, State::LockedRecovery);
    assert!(out.latch);
    // release needs R and A; the warning flag may still be set, so the
    // state after release is Degraded or Normal, never an intervention state
    let out = tick(&mut m, &nominal, premature);
    assert!(!out.latch && out.latch_changed);
    assert!(matches!(out.state, State::Degraded | State::Normal));
    // and eventually Normal once the warning has cleared
    let mut guard = 0;
    while tick(&mut m, &nominal, NONE).state != State::Normal {
        guard += 1;
        assert!(guard < 100_000);
    }
}

#[test]
fn theorem_9_1_separation() {
    let mut r = Rng(10);
    for _ in 0..5_000 {
        let (ut, tt, ud, td) = (
            r.log_uniform(0.1, 10.0),
            r.log_uniform(0.1, 10.0),
            r.log_uniform(0.1, 10.0),
            r.log_uniform(0.1, 10.0),
        );
        let feasible = separation_feasible(ut, tt, ud, td);
        let mut found = None;
        for i in -160..=120 {
            let alpha = 10f64.powf(i as f64 / 20.0);
            if let Some((lo, hi)) = threshold_interval(alpha, ut, tt, ud, td) {
                if found.is_none_or(|(_, l, h): (f64, f64, f64)| hi - lo > h - l) {
                    found = Some((alpha, lo, hi));
                }
            }
        }
        if !feasible {
            assert!(
                found.is_none_or(|(_, lo, hi)| hi - lo < 1e-12),
                "design exists though criterion fails"
            );
        } else if let Some((alpha, lo, hi)) = found {
            let zc = 0.5 * (lo + hi);
            let mut a = acc(alpha, 0.0);
            a.step(ut, tt, true);
            assert!(a.value() < zc, "tolerated transient reached the threshold");
            let mut b = acc(alpha, 0.0);
            b.step(ud, td, true);
            assert!(b.value() >= zc, "required detection missed");
        } else {
            let margin = (ud - ut).max(ud * td - ut * tt);
            assert!(
                margin < 1e-3 * ud.max(ut) * td.max(tt).max(1.0),
                "feasible but no design on the grid"
            );
        }
    }
}

#[test]
fn worked_example_9_2() {
    let (lo, hi, s, eps) = (5.5, 6.5, 0.5, 0.05);
    let dead = eps / s;
    let u_tol = response(0.3 / s + eps / s, dead, 1.0);
    let u_det = response(0.55 / s - eps / s, dead, 1.0);
    assert!((u_tol - 0.6).abs() < 1e-12 && (u_det - 0.9).abs() < 1e-12);
    assert!(separation_feasible(u_tol, 0.2, u_det, 2.0));
    let (a, b) = threshold_interval(1.0, u_tol, 0.2, u_det, 2.0).unwrap();
    assert!((a - 0.10876).abs() < 1e-5 && (b - 0.77820).abs() < 1e-5);
    assert!((time_to_threshold(1.0, u_det, 0.6, 0.0) - 3f64.ln()).abs() < 1e-12);
    let p_max = response(
        deviation(0.0, lo, hi, s).max(deviation(10.0, lo, hi, s)),
        dead,
        1.0,
    );
    assert!((p_max - 10.9).abs() < 1e-12);
    assert!((rise_time(1.0, p_max, 0.15, 0.3) - 0.014051).abs() < 1e-6);
    assert!((intermittent_peak_limit(1.0, u_det, 0.3, 0.1) - 0.7075).abs() < 1e-4);
    assert_eq!(
        intermittent_cycles_to_threshold(1.0, u_det, 0.3, 0.1, 0.6),
        5.0
    );
    assert!(intermittent_cycles_to_threshold(1.0, u_det, 0.2, 0.2, 0.6).is_infinite());
    let e = guard_band_f64(1.0, p_max, f64::INFINITY, 1e-3, 1e-2);
    assert!(e > 8.4e-12 && e < 9.0e-12, "guard band {e}");
}
